#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

// Tensor-core implicit-GEMM 3x3 conv (stride=1, pad=0), bf16 in/out, fp32 accumulate.
// C_in = 3, C_out = 32, K = 3x3 -> implicit GEMM with M = 32 (output channels),
// N = 16x32 spatial tile, K = 27 zero-padded to 32. Weights and the im2col input
// tile are staged in shared memory as bf16 matrices whose layouts match the
// nvcuda::wmma 16x16x16 tensor-core MMA load layout (8 warps split 32 N-tiles).
__global__ __launch_bounds__(256)
void conv2d_3x3_bf16_kernel(
    const __nv_bfloat16* __restrict__ X,
    const __nv_bfloat16* __restrict__ Wt,
    __nv_bfloat16* __restrict__ Y,
    int H, int W, int Hout, int Wout)
{
  using namespace cute;
  using namespace nvcuda;
  constexpr int CI      = 3;
  constexpr int CO      = 32;
  constexpr int K       = 3;
  constexpr int TH      = 16;
  constexpr int TW      = 32;
  constexpr int TILE_N  = TH * TW;        // 512 spatial positions per CTA
  constexpr int TILE_LD = TILE_N + 8;     // skewed sB leading dim reduces bank conflicts
  constexpr int K_DIM   = CI * K * K;     // 27
  constexpr int K_PAD   = 32;             // padded to two 16-wide MMA k-slices
  constexpr int THREADS = 256;
  const int n   = blockIdx.z;
  const int oh0 = blockIdx.y * TH;
  const int ow0 = blockIdx.x * TW;
  const int tid = threadIdx.x;
  // Global tensors for this image, described with CUTE layouts
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)n * CI * H * W),
                        make_shape(Int<CI>{}, H, W),
                        make_stride((int64_t)H * W, (int64_t)W, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * CO * Hout * Wout),
                        make_shape(Int<CO>{}, Hout, Wout),
                        make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));
  auto mW = make_tensor(make_gmem_ptr(Wt),
                        make_shape(Int<CO>{}, Int<K_DIM>{}),
                        make_stride(Int<K_DIM>{}, Int<1>{}));
  // Shared-memory operands in bf16, laid out for direct WMMA loads:
  //   sA: [CO][K_PAD]     row-major weights (M x K), zero-padded along K
  //   sB: [K_PAD][TILE_N] row-major im2col input (K x N), zero-filled halo
  constexpr int TILE_H_IN = TH + K - 1;
  constexpr int TILE_W_IN = TW + K - 1;
  __shared__ __align__(32) __nv_bfloat16 sA[CO * K_PAD];
  __shared__ __align__(32) __nv_bfloat16 sB[K_PAD * TILE_LD];
  __shared__ __align__(32) __nv_bfloat16 sX[CI * TILE_H_IN * TILE_W_IN];
  __shared__ __align__(16) float sC[8][16][16];
  // Cooperative fill of the weight operand (A = [oc, k], row-major, K zero-padded)
  for (int idx = tid; idx < CO * K_PAD; idx += THREADS) {
    const int oc = idx / K_PAD;
    const int k  = idx - oc * K_PAD;
    sA[idx] = (k < K_DIM) ? mW(oc, k) : __float2bfloat16(0.0f);
  }
  // Stage each input activation once in shared memory. The im2col operand is
  // then expanded from this compact 3x18x34 tile, avoiding up to nine global-
  // memory reloads of the same activation across the 3x3 kernel window.
  for (int idx = tid; idx < CI * TILE_H_IN * TILE_W_IN; idx += THREADS) {
    const int ic  = idx / (TILE_H_IN * TILE_W_IN);
    const int rem = idx - ic * (TILE_H_IN * TILE_W_IN);
    const int r   = rem / TILE_W_IN;
    const int c   = rem - r * TILE_W_IN;
    const int ih  = oh0 + r;
    const int iw  = ow0 + c;
    sX[idx] = (ih < H && iw < W) ? mX(ic, ih, iw) : __float2bfloat16(0.0f);
  }
  __syncthreads();
  // Cooperative expansion of the compact input tile into the im2col operand
  // (B = [k, r * TW + c], row-major). Vectorized fill: each thread packs 8
  // consecutive spatial positions into one 16B shared-memory store, so the
  // k/r/c/ic/kh/kw index math is amortized 8x. A vector never crosses a
  // compact-tile row because c + 7 + kw <= 24 + 7 + 2 = 33 = TILE_W_IN - 1.
  // Rows 27..31 are written as zeros; the sp halo [512,520) is never read.
  constexpr int VEC_B  = 8;
  constexpr int NVEC_B = TILE_N / VEC_B;   // 64 vectors per k-row
  for (int idx = tid; idx < K_PAD * NVEC_B; idx += THREADS) {
    const int k  = idx / NVEC_B;
    const int vg = idx - k * NVEC_B;
    uint4 pk = make_uint4(0u, 0u, 0u, 0u);
    if (k < K_DIM) {
      const int r  = vg >> 2;
      const int c  = (vg & 3) * VEC_B;
      const int ic = k / (K * K);
      const int kr = k - ic * (K * K);
      const int kh = kr / K;
      const int kw = kr - kh * K;
      const __nv_bfloat16* src = &sX[(ic * TILE_H_IN + (r + kh)) * TILE_W_IN + c + kw];
      __nv_bfloat16* dst = reinterpret_cast<__nv_bfloat16*>(&pk);
      #pragma unroll
      for (int j = 0; j < VEC_B; ++j) {
        dst[j] = src[j];
      }
    }
    *reinterpret_cast<uint4*>(&sB[k * TILE_LD + vg * VEC_B]) = pk;
  }
  __syncthreads();
  // 8 warps split the 32 16-wide N-tiles (4 each); every warp covers both
  // 16-row M-tiles and both 16-wide K-slices with tensor-core MMAs.
  const int warp = tid >> 5;
  const int lane = tid & 31;
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[2][4];
  #pragma unroll
  for (int m = 0; m < 2; ++m) {
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
      wmma::fill_fragment(acc[m][t], 0.0f);
    }
  }
  #pragma unroll
  for (int kk = 0; kk < 2; ++kk) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a_frag[2];
    wmma::load_matrix_sync(a_frag[0], &sA[kk * 16], K_PAD);
    wmma::load_matrix_sync(a_frag[1], &sA[16 * K_PAD + kk * 16], K_PAD);
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
      const int ncol = (warp * 4 + t) * 16;
      wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b_frag;
      wmma::load_matrix_sync(b_frag, &sB[kk * 16 * TILE_LD + ncol], TILE_LD);
      wmma::mma_sync(acc[0][t], a_frag[0], b_frag, acc[0][t]);
      wmma::mma_sync(acc[1][t], a_frag[1], b_frag, acc[1][t]);
    }
  }
  // Store each 16x16 fp32 tile through shared memory, then write bf16 outputs
  // with bounds checks (spatial index decomposes as r * TW + c).
  #pragma unroll
  for (int m = 0; m < 2; ++m) {
    #pragma unroll
    for (int t = 0; t < 4; ++t) {
      wmma::store_matrix_sync(&sC[warp][0][0], acc[m][t], 16, wmma::mem_row_major);
      __syncwarp();
      #pragma unroll
      for (int i = lane; i < 128; i += 32) {
        const int fr = i >> 3;
        const int fp = (i & 7) * 2;
        const int oc = m * 16 + fr;
        const int sp = (warp * 4 + t) * 16 + fp;
        const int r  = sp >> 5;
        const int c  = sp & 31;
        const int oh = oh0 + r;
        const int ow = ow0 + c;
        if (oh < Hout && ow < Wout) {
          const float v0 = sC[warp][fr][fp];
          const float v1 = sC[warp][fr][fp + 1];
          __nv_bfloat16* p = &mY(oc, oh, ow);
          if (ow + 1 < Wout &&
              ((reinterpret_cast<unsigned long long>(p) & 0x3ULL) == 0)) {
            __nv_bfloat162 pk;
            pk.x = __float2bfloat16(v0);
            pk.y = __float2bfloat16(v1);
            *reinterpret_cast<__nv_bfloat162*>(p) = pk;
          } else {
            p[0] = __float2bfloat16(v0);
            if (ow + 1 < Wout) {
              p[1] = __float2bfloat16(v1);
            }
          }
        }
      }
      __syncwarp();
    }
  }
}
